import{H as e,V as t,et as n,j as r}from"./chunks/framework.BY5yoHkb.js";var i=JSON.parse(`{"title":"PoorerArt ARG：藏在游戏主页里的求救信号","description":"","frontmatter":{"title":"PoorerArt ARG：藏在游戏主页里的求救信号","date":"2026-10-31T00:00:00.000Z","rss":true,"hidden":false,"category":"puzzle","author":["夜鸦kora","杰出维尔汀","ADsurfb0ard","时咨月"],"tags":["PoorerArt","ARG","解谜","密码学","拉普拉斯谜题小课堂"]},"headers":[],"relativePath":"posts/puzzle/PoorerArt-ARG.md","filePath":"posts/puzzle/PoorerArt-ARG.md"}`),a={name:`posts/puzzle/PoorerArt-ARG.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="poorerart-arg-藏在游戏主页里的求救信号" tabindex="-1">PoorerArt ARG：藏在游戏主页里的求救信号 <a class="header-anchor" href="#poorerart-arg-藏在游戏主页里的求救信号" aria-label="Permalink to “PoorerArt ARG：藏在游戏主页里的求救信号”">​</a></h1><blockquote><p><strong>阅读提示：</strong> 本文包含 PoorerArt ARG 的解谜过程与结局剧透。游戏本体含跳脸微恐内容，若要亲自游玩，请做好一定心理准备。</p></blockquote><p>2025 年 3 月 28 日，一位神秘游戏制作者在 Patreon 发布了一个神秘帖子。这本是互联网上每天都在发生的小事，这一次却并不像看起来这么简单。</p><p>Patreon 是一个创作者订阅平台，很多独立作者在这里发布作品，通过支持者的“爱发电”支持创作。从 3 月 28 日开始，这位作者陆续发布帖子，介绍自己的游戏和世界观：开发日志、更新公告、角色之间的小剧场漫画……资料采集时，页面共显示 40 条帖子。翻看起来，这只是一个勤勤恳恳，甚至有些冷清的独立游戏主页。</p><p>但仔细观察，就会察觉到这个主页处处散发着一种诡异的氛围。</p><p>欢迎各位研究员们到此交流。我是哑谜。在拉普拉斯科算中心的支持下，我们与空白解谜组合作推出《拉普拉斯谜题小课堂》，希望带大家了解更多解谜知识，发现谜题的乐趣。本期，我们先来了解 PoorerArt ARG。</p><h2 id="一、签名与隐藏的求救信号" tabindex="-1">一、签名与隐藏的求救信号 <a class="header-anchor" href="#一、签名与隐藏的求救信号" aria-label="Permalink to “一、签名与隐藏的求救信号”">​</a></h2><p>先看账号的签名：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>An original game on Patreon, Fqpv nkuvgp vq jko</span></span></code></pre></div><p>前半句很正常——“Patreon 上的一个原创游戏”。后半句却像随手打出的乱码。不过，乱码不会乱得这么整齐：单词之间留有空格，字母也都来自普通的英文字母表。</p><p>把每个字母在字母表中向前回退两位，<code>F</code> 变成 <code>D</code>，<code>q</code> 变成 <code>o</code>，就能得到：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Fqpv nkuvgp vq jko</span></span>
<span class="line"><span>Dont listen to him</span></span></code></pre></div><p>这就是凯撒密码：对字母使用固定的循环移位。这里的解码偏移为 −2，越过 <code>a</code> 时从字母表末尾继续计算。原串没有撇号，严格解码结果也是 <code>Dont</code>；按自然英语理解，就是“Don&#39;t listen to him”——<strong>别听他的。</strong></p><p>一个作者，在自己游戏的宣传位上警告访客“别听他的”。可账号的主人，不就是作者自己吗？</p><p>再看那张写着“Poorer Art”的涂鸦小人图。手绘小人、一片温馨，仿佛能看到一位慈祥的老奶奶。但仔细检查原图、增强局部对比后，小人脚下会显出一行极淡的黄色文字：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>HELP ME</span></span></code></pre></div><p>救救我。</p><p>这里并不是从无到有画出一句求救，也不是把图片里的字母换成另一套字母，而是让源图中已经存在的低对比信息显现出来。对白底上的淡黄色文字，单纯提高整幅图片亮度未必有效，还要观察颜色和背景之间的差别。</p><p>求救信号不在帖子深处。它从页面的最顶端，就已经开始了。</p><h2 id="二、一个账号-三套声线" tabindex="-1">二、一个账号，三套声线 <a class="header-anchor" href="#二、一个账号-三套声线" aria-label="Permalink to “二、一个账号，三套声线”">​</a></h2><p>继续往下翻，诡异之处越来越多。某些帖子里会毫无上下文地出现密文和意义不明的扭曲图片；4 月下旬，有一篇帖子的正文只有 <code>myfault</code>——“是我的错”——重复了几十遍。</p><p>另一篇帖子的开头写着：</p><blockquote><p>Marco here.</p><p>我是马可。</p></blockquote><p>一个游戏角色，在作者的账号上直接发言。他说，现在 P 消失了，他终于有时间找出秘密，建造自己的逃生通道。但这并不容易，因为“他”还在附近。</p><p>此外，另一篇帖子只有一行字：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ALL LIES.</span></span></code></pre></div><p>都是谎言。</p><p>P、马可，还有那个“他”。一个账号，三套声线，阿莱夫来了都得先确认一下这里有没有自己的工位。</p><p>通过阅读帖子，我们可以辨认出两位主要角色：马可（Marco）和布兰登（Brendan）。马可明显试图跳出帖子本身，向屏幕外的读者传递额外信息。至于布兰登……我们先记住这个名字。</p><p>他们是谁？和作者是什么关系？那场反复被提及的“悲剧”又是什么？帖子没有直接给出答案。部分信息使用 Base64、ASCII、摩斯、盲文或凯撒密码等方式处理；这些方式的原理并不相同，也不能一概称为加密。接下来，我们只展开与主要解谜流程有关的部分。</p><h2 id="三、游戏文件与-dontreadme" tabindex="-1">三、游戏文件与 DONTReadMe <a class="header-anchor" href="#三、游戏文件与-dontreadme" aria-label="Permalink to “三、游戏文件与 DONTReadMe”">​</a></h2><p>解压游戏文件后，会得到三个 ZIP 压缩包和一份文本：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Past.zip</span></span>
<span class="line"><span>PoorerArt.zip</span></span>
<span class="line"><span>Visualizer.zip</span></span>
<span class="line"><span>DONTReadMe.txt</span></span></code></pre></div><p>其中，<code>Past.zip</code> 和 <code>PoorerArt.zip</code> 需要密码；<code>Visualizer.zip</code> 可以直接解压。</p><p>各位研究员，让我们先打开那份名字就很可疑的说明书。区别于寻常的 Readme，它叫作 <code>DONTReadMe</code>——“别读我”。里面写道：</p><blockquote><p>You don&#39;t know what to do? You should probably check out my Patreon...</p><p>不知道该做什么？那你大概应该去看看我的 Patreon……</p></blockquote><p>随后是一长串八位一组的二进制数。把每组二进制转换成数值，再按 ASCII 字符表查找，就能还原文字。例如：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>01000001 → 64 + 1 = 65 → A</span></span>
<span class="line"><span>01101110 → 64 + 32 + 8 + 4 + 2 = 110 → n</span></span></code></pre></div><p>需要区分的是：ASCII 本身是七位字符编码，这里用最高位为零的八位字节表示它，并不意味着 ASCII 本身变成了八位编码。<a href="https://www.rfc-editor.org/rfc/rfc20.html" target="_blank" rel="noreferrer">RFC 20</a> 也采用了这种表示方式。</p><p>逐组转换后，警告显现出来：</p><blockquote><p>And be careful. HE is watching.</p><p>小心。“他”在看着。</p></blockquote><p>第二次警告，第二次被强调的“他”。签名里说“别听他的”，说明书里说“他在看着”。这个故事究竟还隐藏着什么？</p><h2 id="四、感谢文本里的-base64" tabindex="-1">四、感谢文本里的 Base64 <a class="header-anchor" href="#四、感谢文本里的-base64" aria-label="Permalink to “四、感谢文本里的 Base64”">​</a></h2><p>购买游戏还会得到一份感谢文本，其中有这样一串字符：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>VGhhbmsgeW91ISBOb3cgcGxlYXNlLCBoZWxwIG1lIQ==</span></span></code></pre></div><p>大小写字母、数字、规整的长度，以及结尾的 <code>==</code>，都提示我们尝试 Base64 解码。</p><p>Base64 使用 64 个符号表示六位数值，把四个符号表示的 24 位重新分成三个八位字节，再还原原始数据。标准字母表还包含 <code>+</code> 和 <code>/</code>；结尾的 <code>=</code> 用于补位，但不是每一串 Base64 都需要等号。具体规则见 <a href="https://www.rfc-editor.org/rfc/rfc4648.html" target="_blank" rel="noreferrer">RFC 4648</a>。</p><p>以前四个字符为例：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>V      G      h      h</span></span>
<span class="line"><span>21     6      33     33</span></span>
<span class="line"><span>010101 000110 100001 100001</span></span>
<span class="line"><span></span></span>
<span class="line"><span>01010100 01101000 01100001</span></span>
<span class="line"><span>T        h        a</span></span></code></pre></div><p>完整解码结果是：</p><blockquote><p>Thank you! Now please, help me!</p><p>谢谢你！现在，请帮帮我！</p></blockquote><p>付钱的人收到感谢，感谢的末尾却是求救。各位，这笔交易从一开始就不对劲。</p><h2 id="五、visualizer-没有更多西瓜了" tabindex="-1">五、Visualizer：没有更多西瓜了 <a class="header-anchor" href="#五、visualizer-没有更多西瓜了" aria-label="Permalink to “五、Visualizer：没有更多西瓜了”">​</a></h2><p>接下来，打开唯一能直接解压的 Visualizer。这是一个视角解谜小游戏：场景中散落着看似毫无规律的碎片，需要转动视角、缩放画面，把它们对齐到特定角度。</p><p>对齐成功的一瞬间，混乱的色块会拼成完整图案，其中包括粉色西瓜；画面里还会出现用于后续解谜的字母组。</p><p>按现有解谜资料，五关得到的字符串依次为：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>WAT / ORE / LONS / ERME / NOM</span></span></code></pre></div><p>按关卡顺序拼接：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>WATORELONSERMENOM</span></span></code></pre></div><p>它看起来像乱码，但若尝试字母重排，就能得到一句符合这些字母数量的英语：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>NO MORE WATERMELONS</span></span></code></pre></div><p>没有更多西瓜了。</p><p>这里有一个容易漏掉的细节：原串共有 <strong>17 个字母</strong>，所以结尾必须保留复数 <code>S</code>。单数 <code>NO MORE WATERMELON</code> 只有 16 个字母，不能算作完整重排。复数句与原串的字母及其出现次数完全相同；这里将它作为可复验的重排示例，不额外断言这是作者正式公布的标准谜底。</p><p>于是玩家一路找西瓜、抄字母、拼字符串，最后得到的短句庄严宣布：没有更多西瓜了。很好，世界观没推进，人物没解释，但至少现在我们对西瓜库存有了学术结论。</p><p>真正用于解锁的，是按关卡顺序排列的原串：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>PoorerArt.zip 的密码：WATORELONSERMENOM</span></span></code></pre></div><p>英语重排句帮助我们理解字母，<strong>不能拿它替代实际解压密码</strong>。</p><h2 id="六、past-用-爱-锁住-过去" tabindex="-1">六、Past：用“爱”锁住“过去” <a class="header-anchor" href="#六、past-用-爱-锁住-过去" aria-label="Permalink to “六、Past：用“爱”锁住“过去””">​</a></h2><p>第一道门开了。第二道门的钥匙，仍然藏在 Patreon。</p><p>有一篇名为 Don&#39;t Read——“别读”——的帖子，包含这段字符：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>VGhlIGxldHRlcnMgZm9ybSB0aGUgcGFzc3dvcmQgZm9yIHRoZSBzZWNyZXQgZmlsZXM=</span></span></code></pre></div><p>同样使用 Base64 解码，得到：</p><blockquote><p>The letters form the password for the secret files</p><p>这些字母组成了秘密文件的密码。</p></blockquote><p>哪些字母？线索指向这篇帖子所属的合集 <code>We3k 3</code>，也就是第三周。根据现有解谜资料，合集里的四张图片分别藏着 <code>L</code>、<code>O</code>、<code>V</code>、<code>E</code>，组合起来是：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>LOVE</span></span></code></pre></div><p>爱。这就是 <code>Past.zip</code> 的密码。</p><p>设计者用“爱”锁住了“过去”。请记住这个修辞，它与后面的线索遥相呼应。</p><h2 id="七、悔恨与羞耻" tabindex="-1">七、悔恨与羞耻 <a class="header-anchor" href="#七、悔恨与羞耻" aria-label="Permalink to “七、悔恨与羞耻”">​</a></h2><p>打开 Past 后，里面有五份文件。按照文件名顺序，把各文件标红的字母排列起来，得到：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mzbmzoviyncvhz</span></span></code></pre></div><p>还记得签名的手法吗？这里同样可以使用凯撒移位，但<strong>偏移与签名不同</strong>：不是回退两位，而是前进五位；回退 21 位与前进五位在 26 字母循环中等价。</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>m → r</span></span>
<span class="line"><span>z → e</span></span>
<span class="line"><span>b → g</span></span>
<span class="line"><span></span></span>
<span class="line"><span>mzbmzoviyncvhz → regretandshame</span></span></code></pre></div><p>再按词义分开，得到 <code>regret and shame</code>：悔恨与羞耻。</p><p>第一道线索像冷笑话，第二道是“爱”，第三道是“悔恨与羞耻”。这些不像钥匙，更像一份自白书的章节标题。我们解开的并非只有谜题，也像是某个人的忏悔。</p><h2 id="八、游戏本体-打破拼图循环" tabindex="-1">八、游戏本体：打破拼图循环 <a class="header-anchor" href="#八、游戏本体-打破拼图循环" aria-label="Permalink to “八、游戏本体：打破拼图循环”">​</a></h2><p>现在，回到 PoorerArt，进入游戏本体。前半段是拼图小关卡，随后出现一串选项。按本次整理的解谜路线，这些选项选择 <code>No</code> 后，会进入被反复重置拼图的流程。</p><p>你拼好的拼图，被布兰登一次次重置，只能从头再来。这像一个故意设计的死局，直到马可出现。</p><p>真是浪费我宝贵的修理兔毛手袋“每日下午茶”的时间。</p><p>马可用提示引导玩家打破常规：</p><blockquote><p>freedom in the past.</p><p>自由，在过去里。</p></blockquote><p>“过去”——Past，那个用“爱”打开的文件夹。它留下的十四个字母，现在有了新的用途。</p><p>这时，在拼图页面输入字母，会得到正确或错误的音效反馈。按原顺序键入：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mzbmzoviyncvhz</span></span></code></pre></div><p>注意，输入的仍是<strong>原始十四字母</strong>，不是解码后的 <code>regretandshame</code>。完成输入后，再点击拼图碎片，碎片就会消失，循环终结，关卡跳过。</p><p>说得文艺一点，这是让玩家直面过去；说得直白一点，就是先用十四个字母把人折腾半天，再告诉你“答案其实一直在你键盘上”。要打破现在的僵局，关键在于把过去找到的信息真正带进游戏。</p><h2 id="九、删除囚笼-解救灵魂" tabindex="-1">九、删除囚笼，解救灵魂 <a class="header-anchor" href="#九、删除囚笼-解救灵魂" aria-label="Permalink to “九、删除囚笼，解救灵魂”">​</a></h2><p>流程推进到最后，被解救的 PoorerArt 会提示玩家：要拯救马可的灵魂，需要到游戏文件中寻找马可。</p><p>退出游戏，打开<strong>这份游戏的目录</strong>，进入 <code>StreamingAssets</code> 文件夹，找到名为 <code>marcomarco</code> 的图片文件。按游戏给出的流程移除它，再返回游戏，即可继续进入结局。</p><p>解救一个灵魂的方式，是从文件系统里抹去他的囚笼。</p><h2 id="十、thankyou-反派的致谢信" tabindex="-1">十、ThankYou：反派的致谢信 <a class="header-anchor" href="#十、thankyou-反派的致谢信" aria-label="Permalink to “十、ThankYou：反派的致谢信”">​</a></h2><p>通过花海结局后，再查看 <code>StreamingAssets</code>，会发现多出一份名为 <code>ThankYou</code> 的文本：</p><blockquote><p>So you freed my friend, uh? ...but you also freed me. Yours, Brendan</p><p>你解救了我的朋友，嗯？……但你也释放了我。你的，布兰登。</p></blockquote><p>等等。布兰登？那个亲手重置拼图、把所有人锁进循环里的布兰登，现在居然开始道谢了？这完全不亚于纵火犯站在消防车旁边鞠躬致谢，情绪价值给得很足，责任是一点没少。</p><p>更妙的是，信的末尾还留着一行点与划。按<a href="https://www.itu.int/dms_pubrec/itu-r/rec/m/R-REC-M.1677-1-200910-I!!PDF-E.pdf" target="_blank" rel="noreferrer">国际摩斯字母表</a>逐组解码：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>..- -. - .. .-.. / -. . -..- - / - .. -- .</span></span>
<span class="line"><span>U   N  T I  L     N  E X    T   T I  M  E</span></span>
<span class="line"><span></span></span>
<span class="line"><span>UNTIL NEXT TIME</span></span></code></pre></div><p>下次见。上面的 <code>/</code> 只是书面展示时的词间分隔。</p><p>哦，原来这封信甚至都不是道歉信，而是一封续费通知。</p><p>一封致谢信，落款却是反派，结尾则是“下次见”。看来这个故事，还没有完全落下帷幕。</p><h2 id="十一、拼回完整的故事" tabindex="-1">十一、拼回完整的故事 <a class="header-anchor" href="#十一、拼回完整的故事" aria-label="Permalink to “十一、拼回完整的故事”">​</a></h2><p>先让我们把散落的线索拼回故事。</p><p>PoorerArt（P）是一名游戏制作者；马可（M）是他的好友，也是内容创作者。布兰登（B）与他们之间，则有着更复杂的关系。</p><p><strong>一种剧情解读是：</strong> P 可能存在名为布兰登的恶意人格，并受到它的控制。这可能与后来发生的悲剧有关：P 与 M 在郊外木屋生活时遭遇火灾，M 不幸丧生，而 P 可能与火灾有关。</p><p>沿着这个解释，B 将 M 的灵魂囚禁在游戏中；P 发现好友被困后前往救援，却也被 B 关了进去。玩家循着页面上不断出现的异常信息，发现暗中求助的 P，进入游戏并解救 M 与 P。</p><p>但 ThankYou 的落款又提醒我们：被释放的，也许不止他们。</p><p>这条因果链是对现有线索的复原，而不是所有细节都已得到作者明确确认的设定。关于人格、身体控制与火灾责任，应当保留解读的余地。</p><h2 id="十二、评价与致谢" tabindex="-1">十二、评价与致谢 <a class="header-anchor" href="#十二、评价与致谢" aria-label="Permalink to “十二、评价与致谢”">​</a></h2><p>PoorerArt 的故事不算长，主要谜题的流程也比较清晰。对刚接触 ARG 的研究员来说，它提供了一个从主页异常、编码线索走到游戏文件操作的入门体验。</p><p>它的 meta 元素有一些巧思，例如让玩家亲手处理 <code>marcomarco</code> 才能继续走向结局；具体到单个谜题，部分环节仍略显单薄。但这也正是这类作品的趣味：不必每一道谜题都足够复杂，一串乱码、一张怪图和一次越过游戏窗口边界的操作，也能让人感受到设计者安排线索的心思。</p><p>特别感谢迷雾 wiki 对本系列提供的资料支持，感谢 @Matt 提供 ARG 选材，感谢 @孤舟、@小小幽灵，以及所有参与解谜和制作的朋友。</p><p>欢迎各位研究员交流发现，也欢迎向空白组推荐新的谜题与它们背后的故事。</p><h2 id="资料与整理说明" tabindex="-1">资料与整理说明 <a class="header-anchor" href="#资料与整理说明" aria-label="Permalink to “资料与整理说明”">​</a></h2><ul><li>本文由《拉普拉斯谜题小课堂》EP01 文稿整理，保留哑谜的主持视角；原文稿署名见页首。文字转写、结构整理与部分编码演算复核使用了 AI 辅助。</li><li>帖子数量为资料采集时的页面记录，不代表当前实时数量；部分帖子的具体日期存在差异，因此正文保留较宽泛的时间表述。</li><li>四张 LOVE 图片的逐个藏字位置、Past 五份文件的红字分布，以及完整分支条件，目前所持材料不足以全部独立复现。相应流程依据已有解谜资料整理，不把它们表述为本次逐项重做的结果。</li><li>字母重排、两套凯撒偏移、两段 Base64、ASCII 示例与摩斯结果可按正文给出的输入独立复验。原理更正已写入本文，个别措辞与此前视频的真人录音可能不同。</li><li>作品入口：<a href="https://www.patreon.com/c/PoorerArt" target="_blank" rel="noreferrer">PoorerArt 作者 Patreon</a>、<a href="https://pidoproductions.itch.io/poorerart" target="_blank" rel="noreferrer">作者 itch.io 页面</a>。</li><li>方法资料：<a href="https://www.rfc-editor.org/rfc/rfc4648.html" target="_blank" rel="noreferrer">RFC 4648：Base64 编码</a>、<a href="https://www.rfc-editor.org/rfc/rfc20.html" target="_blank" rel="noreferrer">RFC 20：ASCII</a>、<a href="https://www.itu.int/dms_pubrec/itu-r/rec/m/R-REC-M.1677-1-200910-I!!PDF-E.pdf" target="_blank" rel="noreferrer">ITU-R M.1677-1：国际摩斯电码</a>。</li></ul>`,122)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};